import { useLearning } from '../useLearning.js'
import { icon } from '../assets.js'
import AttemptHistory from './AttemptHistory.vue'
const { state, setAnswer, submitAttempt, hint, loadTask } = useLearning()
</script>
<template><section class="task-panel" v-if="state.run"><div class="section-heading"><h2>{{ state.run.purpose==='review' ? '换一道新题，检查理解' : '轮到你试一试' }}</h2><span>{{ state.run.task.kind==='written' ? '开放作答 · 待复核' : '结果判断' }}</span></div><p class="task-prompt">{{ state.run.task.prompt }}</p><div v-if="state.run.task.kind==='choice'" class="answer-options"><button v-for="option in state.run.task.options" :key="option.id" :class="['answer-option',{selected:state.answer===option.id}]" :disabled="!!state.result || state.taskBusy" @click="setAnswer(option.id)"><span>{{ option.id }}</span>{{ option.text }}</button></div><template v-else><textarea :value="state.answer" @input="setAnswer($event.target.value)" :disabled="!!state.result || state.taskBusy" class="written-answer" aria-label="练习作答" rows="6" placeholder="写下你的判断与依据。原始作答会保存，当前版本不自动认证开放题掌握。"></textarea><details class="rubric"><summary>查看作答标准</summary><p v-for="item in state.run.task.criteria" :key="item">{{ item }}</p></details></template><div v-if="state.hint" class="hint-feedback" role="status"><strong>一点线索</strong><p>{{ state.hint }}</p><small>这次帮助会随作答记录。</small></div><div v-if="!state.result" class="task-actions"><button class="secondary-button" :disabled="state.designPreview || state.hintBusy || state.taskBusy" @click="hint">{{ state.hintBusy ? '获取提示中…' : '给我一点提示' }}</button><button class="primary-button" :disabled="state.designPreview || !state.answer.trim() || state.taskBusy" @click="submitAttempt">{{ state.taskBusy ? '保存与检查中…' : '提交作答' }}<img :src="icon('arrow-right','white')" alt=""></button></div><div v-else :class="['assessment-feedback',state.result.status]" role="status"><strong>{{ state.result.label }}</strong><p>{{ state.result.feedback }}</p><small>{{ state.result.next_step }}</small><div class="task-actions"><button class="secondary-button" @click="loadTask('practice')">重新练习</button><button v-if="state.run.purpose!=='review'" class="primary-button" @click="loadTask('review')">换题复核</button><span v-else class="evidence-reminder">当次表现已保存，延迟保持尚未验证。</span></div></div><p class="help-condition-note">当前任务期间向导师提问也会留下帮助记录；需要未受助复核时，请先独立作答。</p><AttemptHistory/></section><div v-else class="task-loading">正在打开任务…</div></template>
